def source(key,quotes):
 m=M[key]; title,publisher,section,license,version=meta[key];text=(R/m['local_snapshot']).read_text()
 q=[]
 for excerpt,supports in quotes:
  if excerpt not in text: raise ValueError((key,excerpt))
  start=text.index(excerpt); line=text[:start].count('\n')+1
  q.append({'text':excerpt,'supports':supports,'locator':f'{m["local_snapshot"]}:L{line}','derivation_boundary':'Supports the domain operation or criterion; repetition after a change, bounds, authorization, and closure bookkeeping are author policy, not a verbatim manual loop.'})
  subprocess.run(['python',S,'--ledger',str(R/'citation-ledger.json'),'quote',str(ids[key]),'--text',excerpt,'--from',str(R/m['local_snapshot'])],check=True,capture_output=True)
 return {'url':m['url'],'title':title,'publisher':publisher,'section':section,'version':version,'license':license,'local_snapshot':m['local_snapshot'],'sha256':m['sha256'],'quotes':q}
common=['Exit only after a fresh, complete observation satisfies the exit predicate; an initial passing test may exit without operating.','Stop unresolved on missing permission, missing evidence, tool error, stagnation, oscillation, or exhausted max_iterations; never convert exhaustion into success.']
def loop(id,name,domain,profession,objective,test,exit,operate,retest,gestalts,sources,notes,cap=3):
 return {'loop_id':id,'name':name,'domain':domain,'profession':profession,'objective':objective,'initial_test':test,'exit_predicate':exit,'max_iterations':cap,'epistemic_status':'DERIVED','gestalts':{'lexical':gestalts},'procedure':{'operate_step':operate,'retest':retest,'stop_conditions':common.copy()},'sources':sources,'review_required':True,'notes':['AUTHOR POLICY: max_iterations counts operate/fresh-retest cycles, not the initial test; the manuals do not specify this bound.','DERIVED specification only: no domain commands, site edits, database changes, or success trials executed. Fresh retest is explicitly authored by reapplying the cited check to the changed artifact; no source is claimed to prescribe this whole TOTE loop.']+notes}
